// BUG: uses product instead of sum
pub fn sum(nums: &[i64]) -> i64 {
    nums.iter().copied().product()
}

// BUG: returns the minimum instead of the maximum
pub fn max(nums: &[i64]) -> Option<i64> {
    nums.iter().copied().reduce(|a, b| if a < b { a } else { b })
}

// BUG: returns the original vec instead of deduplicating
pub fn dedup(nums: Vec<i64>) -> Vec<i64> {
    nums
}

use vecutils::{sum, max, dedup};

#[test]
fn test_sum() {
    assert_eq!(sum(&[1, 2, 3, 4]), 10);
}

#[test]
fn test_sum_empty() {
    assert_eq!(sum(&[]), 0);
}

#[test]
fn test_max() {
    assert_eq!(max(&[3, 1, 4, 1, 5, 9]), Some(9));
}

#[test]
fn test_max_empty() {
    assert_eq!(max(&[]), None);
}

#[test]
fn test_dedup() {
    let mut v = dedup(vec![1, 2, 2, 3, 3, 3, 4]);
    v.sort();
    assert_eq!(v, vec![1, 2, 3, 4]);
}
